index a571b9a..7afa8ac 100644
--- a/sqlglot/parsers/tsql.py
+++ b/sqlglot/parsers/tsql.py
@@ -357,8 +357,11 @@ class TSQLParser(parser.Parser):
     }

     # T-SQL does not allow BEGIN to be used as an identifier
-    ID_VAR_TOKENS = parser.Parser.ID_VAR_TOKENS - {TokenType.BEGIN}
-    ALIAS_TOKENS = parser.Parser.ALIAS_TOKENS - {TokenType.BEGIN}
+    # OUTPUT (tokenized as RETURNING) is allowed as an identifier so e.g. xp_cmdshell's
+    # result column can be referenced unquoted; the OUTPUT clause is still parsed
+    # positionally in INSERT/UPDATE/DELETE/MERGE.
+    ID_VAR_TOKENS = (parser.Parser.ID_VAR_TOKENS | {TokenType.RETURNING}) - {TokenType.BEGIN}
+    ALIAS_TOKENS = (parser.Parser.ALIAS_TOKENS | {TokenType.RETURNING}) - {TokenType.BEGIN}
     TABLE_ALIAS_TOKENS = (parser.Parser.TABLE_ALIAS_TOKENS | {TokenType.ANTI, TokenType.SEMI}) - {
         TokenType.BEGIN
     }

diff --git a/sqlglot/parsers/tsql.py b/sqlglot/parsers/tsql.py
index a571b9a..145fb66 100644
--- a/sqlglot/parsers/tsql.py
+++ b/sqlglot/parsers/tsql.py
@@ -357,8 +357,12 @@ class TSQLParser(parser.Parser):
     }

     # T-SQL does not allow BEGIN to be used as an identifier
-    ID_VAR_TOKENS = parser.Parser.ID_VAR_TOKENS - {TokenType.BEGIN}
-    ALIAS_TOKENS = parser.Parser.ALIAS_TOKENS - {TokenType.BEGIN}
+    # OUTPUT (tokenized as RETURNING) is not reserved in T-SQL, e.g. xp_cmdshell's
+    # result column is named `output`, so allow it as an identifier / column alias.
+    # It is deliberately excluded from TABLE_ALIAS_TOKENS so the OUTPUT clause in
+    # DELETE/UPDATE/INSERT isn't swallowed as an implicit table alias.
+    ID_VAR_TOKENS = (parser.Parser.ID_VAR_TOKENS | {TokenType.RETURNING}) - {TokenType.BEGIN}
+    ALIAS_TOKENS = (parser.Parser.ALIAS_TOKENS | {TokenType.RETURNING}) - {TokenType.BEGIN}
     TABLE_ALIAS_TOKENS = (parser.Parser.TABLE_ALIAS_TOKENS | {TokenType.ANTI, TokenType.SEMI}) - {
         TokenType.BEGIN
     }

